INSERT INTO feature VALUES('temporal-judgement','sessions','The temporal judgement (logical time as a web)','session-types','partial','uncommon','dependent provers','A session''s logical time is a two-colour causal web — each endpoint''s own order and every send before its receipt green, every other pair white — and a recorded dialogue is admitted exactly when its order linearizes the web; a receipt recorded before its send is refused by name. A source writes a binary session''s dialogue as `dialogue(left(…), right(…), …) : Dialogue(S)`, its left endpoint following `S` and its right the dual; two logs that commute independent moves are one dialogue, related by `refl`, and a receipt of another payload or label is refused as unmatched.','core-session theory-deep-inference core-term core-checker core-nbe surface-lowering','crates/core-session/tests/dialogue.rs crates/theory-deep-inference/src/causal_web.rs corpus/model/sessions/dialogue-web.gandr corpus/pathological/sessions/dialogue-web.gandr crates/core-checker-base/tests/flow.rs::a_dialogue_checks_by_its_web_and_refuses_by_move','corpus/ledger/features/temporal-judgement.gandr','#316');
